mapper.select:
select trip_id, rule_id, rule_code, metric, scope, agent_code, metric_value, sample_size, threshold, window_start, action, dedup_key,
       resolved_by, resolved_time, create_time
from abr_breaker_trip

    and rule_code = #{ruleCode}
    and agent_code = #{agentCode}
    and scope = #{scope}

        and create_time >= cast(#{params.beginTime} as date)


        and create_time < cast(#{params.endTime} as date) + interval '1 day'


order by trip_id desc
